<div class="page-heading"><div><span class="eyebrow">Admin · Vaccine list</span><h1>Availability overview</h1><p>See which vaccines are available or unavailable across active hospitals.</p></div></div>
<section class="vaccine-summary-grid">
<?php foreach ($vaccines as $vaccine): ?><article><div><span class="age-dot"><?= (int) $vaccine['recommended_age_months'] ?></span><small>months</small></div><h2><?= e($vaccine['name']) ?></h2><p><?= e($vaccine['dose_label']) ?> · <?= e($vaccine['disease']) ?></p><strong><?= (int) $vaccine['available_hospitals'] ?> hospital<?= (int) $vaccine['available_hospitals'] === 1 ? '' : 's' ?> available</strong><small><?= (int) $vaccine['total_stock'] ?> total units reported</small></article><?php endforeach; ?>
</section>
<section class="panel table-panel"><div class="panel-heading"><div><span class="eyebrow">Hospital detail</span><h2>Available / unavailable list</h2></div></div>
<div class="table-scroll"><table><thead><tr><th>Hospital</th><th>Vaccine</th><th>Status</th><th>Stock</th><th>Last updated</th></tr></thead><tbody><?php foreach ($availability as $item): ?><tr><td><strong><?= e($item['hospital_name']) ?></strong><small><?= e($item['city']) ?></small></td><td><?= e($item['vaccine_name']) ?><small><?= e($item['dose_label']) ?></small></td><td><span class="status status-<?= $item['is_available'] && $item['stock_quantity'] > 0 ? 'available' : 'unavailable' ?>"><?= $item['is_available'] && $item['stock_quantity'] > 0 ? 'Available' : 'Unavailable' ?></span></td><td><?= (int) $item['stock_quantity'] ?></td><td><?= e(display_date($item['updated_at'], 'd M Y, g:i A')) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
